import re
import os

# Keywords to identify completed projects
completion_keywords = ['竣工', '完工', '交付', '启用', '投产', '通过验收', '移交', '开通运营', '正式运营']

reports_dir = '/workspace'
projects = []

for filename in sorted(os.listdir(reports_dir)):
    if filename.startswith('reports_p_') and filename.endswith('.txt'):
        with open(os.path.join(reports_dir, filename), 'r') as f:
            content = f.read()

        # Split by company mentions to extract project entries
        # Each project entry starts with a company name line
        lines = content.split('\n')
        current_entry = []

        for line in lines:
            line = line.strip()
            if any(kw in line for kw in completion_keywords):
                current_entry.append(line)
            elif line and not any(kw in content[content.find(line):content.find(line)+500] for kw in completion_keywords):
                if '承建' in line or '承包' in line or '援建' in line:
                    if current_entry:
                        projects.append('\n'.join(current_entry))
                    current_entry = [line]
                elif current_entry and len(line) < 50 and ('公司' in line or '集团' in line):
                    current_entry.append(line)
            elif current_entry:
                current_entry.append(line)

        if current_entry:
            projects.append('\n'.join(current_entry))

for p in projects:
    print(p)
    print("-" * 80)
EOF
